# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_aer_a import B
W=[
E('aircrew','英 /ˈeəkruː/；美 /ˈerkruː/','机组人员；飞行机组','把一架航空器上负责执行飞行任务的人看作一个团队。','air + crew 一组共同工作的人员；把船员等 crew 用法扩展到航空。',B+[['air + crew → aircrew','在飞机上执行任务的工作人员']],'aircrew 常出现在航空、尤其军用飞行语境，指飞行员及其他机上执行任务的人员。aircrew training 是机组训练。它不是所有乘客的总称，具体包含哪些岗位取决于飞行任务。','aircrew members；aircrew training；experienced aircrew。','aircrew 是机组，passengers 是乘客；cabin crew 特别指客舱服务与安全工作的乘务组，范围较具体。',('The aircrew reviewed the weather before departure.','机组在出发前查看了天气情况。'),('All aircrew members took part in the briefing.','所有机组成员都参加了任务简报。'),sources=['https://en.wiktionary.org/wiki/aircrew','https://www.oxfordlearnersdictionaries.com/definition/english/aircrew']),
E('airfare','英 /ˈeəfeə/；美 /ˈerfer/','机票价格；航空票价','fare 本来就是乘车乘船的钱，放到 air 后就成了乘飞机的钱。','air + fare 交通票价；不是 air + fair 公平。',B+[['air + fare → airfare','航空旅行所付的票款']],'compare airfares 是比较机票价格；airfare included 表示费用包含机票。它通常说价格或费用，而不是作为凭证的那张纸或电子票。','low airfares；return airfare；airfare included；the cost of airfare。','airfare 是价格，air ticket 是机票。说 the airfare is high 是票价高，不是飞机飞得高。',('The package includes accommodation but not airfare.','套餐包含住宿，但不包含机票费用。'),('Airfares tend to be higher during the holiday period.','假日期间的机票价格往往更高。'),sources=['https://en.wiktionary.org/wiki/airfare','https://www.oxfordlearnersdictionaries.com/definition/english/airfare']),
E('airfield','英 /ˈeəfiːld/；美 /ˈerfiːld/','飞行场；飞机起降场','先有一块能让飞机起飞、降落的平坦地面，再谈周围建了什么设施。','air + field 场地；不是空中的田野，而是供飞行使用的地面。',B+[['air + field → airfield','用于飞机起降的场地']],'a military airfield 是军用飞行场；a small airfield 可能只有简单的跑道和机库，不一定有大型客运航站楼。这个词把重点放在起降场地。','a military airfield；a disused airfield；land at an airfield。','airport 通常让人想到完整的机场运营设施；airfield 更突出场地，两者有重叠，并非一条绝对的大小分界。',('The plane landed at a small airfield outside town.','飞机降落在城外一处小型飞行场。'),('The former military airfield is now used by a flying club.','那处原军用飞行场如今由一家飞行俱乐部使用。'),sources=['https://en.wiktionary.org/wiki/airfield','https://www.oxfordlearnersdictionaries.com/definition/english/airfield']),
E('airship','英 /ˈeəʃɪp/；美 /ˈerʃɪp/','飞艇','想象一艘浮在空中的长船：充气体提供浮力，再靠动力和控制装置航行。','air + ship；早期可泛指空中航行器，现代通常指能够操纵、由动力推进的飞艇。',B+[['air + ship → airship','空中的船 → 动力飞艇']],'飞艇常有一个巨大的气囊状主体，下方或内部安置人员和设备。它和普通热气球的区别不只是大小，而是典型地具备动力和操纵能力。','a passenger airship；a rigid airship；an airship hangar。','airship 不是任何飞机的常用同义词。现代说 airplane，一般不会让人想到巨大的充气飞艇。',('The airship moved slowly above the stadium.','飞艇缓缓地从体育场上空驶过。'),('The museum contains photographs of early passenger airships.','博物馆收藏了早期载客飞艇的照片。'),sources=['https://en.wiktionary.org/wiki/airship','https://www.oxfordlearnersdictionaries.com/definition/english/airship']),
E('airlift','英 /ˈeəlɪft/；美 /ˈerlɪft/','空运；用飞机或直升机运送','地面道路走不通，就把人或物资从空中抬过去。','air + lift 提起、运送；可作名词，也可作动词。',B+[['air + lift → airlift','通过空中提运 → 空运行动']],'an emergency airlift 是紧急空运；airlift supplies 是用飞机运送物资；airlift somebody to hospital 是用航空器把人转送到医院，常见于救援报道。','airlift supplies；an emergency airlift；airlift people out of an area。','airlift 强调运输行动，尤其紧急或地面受阻时；ordinary flight 只说普通飞行或航班。',('Helicopters airlifted food to the isolated villages.','直升机把食物空运到了与外界隔绝的村庄。'),('The airlift continued after the roads were cut off.','道路中断后，空运仍在继续。'),sources=['https://en.wiktionary.org/wiki/airlift','https://www.oxfordlearnersdictionaries.com/definition/english/airlift_1']),
E('airway','英 /ˈeəweɪ/；美 /ˈerweɪ/','气道；航路','给空气留一条路，是身体气道；给飞机规划一条路，是空中航路。','air + way 路径；根据 air 指空气还是航空，形成两类常见含义。',B+[['air + way → airway','空气通过的路径；飞机航行的路线']],'the upper airway 在身体语境指上气道；a busy airway 在航空语境指繁忙航路。Airways 也常出现在航空公司名称中，这时是公司的名字部分，不要按器官理解。','the upper airway；airway obstruction；an airway route；Airways〔公司名中〕。','airway 是供空气或飞机通过的路，airline 通常是航空公司。二者有关联，但不是同义替换。',('The diagram shows the upper airway.','图中展示了上气道。'),('The aircraft joined a busy airway over the coast.','飞机在海岸上空进入了一条繁忙航路。'),sources=['https://en.wiktionary.org/wiki/airway','https://www.oxfordlearnersdictionaries.com/definition/english/airway']),
E('aerosol','英 /ˈeərəsɒl/；美 /ˈerəsɔl/','气溶胶；喷雾剂；喷雾罐','很多极小的固体颗粒或液滴悬在空气里，像一团细细的雾。','近代 aero- 空气 + sol 溶胶；sol 本身与 solution 的缩短形式有关。不是太阳 sol，也不表示颗粒真的溶成了气体。',[['希腊 aer → aero-','空气'],['aero- + sol → aerosol','颗粒或液滴分散在气体中的体系'],['日常商品语境','喷雾剂或装喷雾剂的罐']],'科学语境的 aerosol 是细小固体、液滴或两者分散在气体中形成的体系，雾和烟都能提供直观联想。日常说 an aerosol，则可能指喷雾罐；并非只有罐子喷出的东西才是气溶胶。','aerosol particles；an aerosol spray；an aerosol can；atmospheric aerosols。','aerosol 与 gas 不是同一概念：气溶胶中还有悬浮的颗粒或液滴。词中 sol 的历史来源不能替代今天的科学定义。',('The researchers measured aerosol particles in the air.','研究人员测量了空气中的气溶胶颗粒。'),('The product is sold as an aerosol spray.','这种产品以罐装喷雾的形式出售。'),sources=['https://www.etymonline.com/word/aerosol','https://goldbook.iupac.org/terms/view/A00176/plain','https://en.wiktionary.org/wiki/aerosol'])
]
